  });

  const issuedResult = issueInvoice(invoiceResult.value, []);
  // Manually remove dueDate
  const invoiceWithoutDueDate = { ...issuedResult.value };
  delete invoiceWithoutDueDate.dueDate;

  const result = overdueInvoices([invoiceWithoutDueDate], '2024-10-20');

  assert.equal(result.length, 0);
});

test('overdueInvoices: multiple invoices sorted by most overdue first', () => {
  const inv1 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-01',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
      terms: 'NET14',
    }).value,
    []
  ).value;

  const inv2 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-05',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
      terms: 'NET14',
    }).value,
    []
  ).value;

  const inv3 = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-10-10',
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
      terms: 'NET14',
    }).value,
    []
  ).value;

  // Due dates: inv1=2024-10-15, inv2=2024-10-19, inv3=2024-10-24
  // As of 2024-10-25: inv1 is 10 days overdue, inv2 is 6 days, inv3 is 1 day
  const result = overdueInvoices([inv3, inv1, inv2], '2024-10-25');

  assert.equal(result.length, 3);
  assert.equal(result[0].daysOverdue, 10);
  assert.equal(result[1].daysOverdue, 6);
  assert.equal(result[2].daysOverdue, 1);
  assert.equal(result[0].number, inv1.number);
  assert.equal(result[1].number, inv2.number);
  assert.equal(result[2].number, inv3.number);
});

