  ).value;

  // Due dates: inv1=2024-10-15, inv2=2024-10-19, inv3=2024-10-24
  // As of 2024-10-25: inv1 is 10 days overdue, inv2 is 6 days, inv3 is 1 day
  const result = overdueInvoices([inv3, inv1, inv2], '2024-10-25');

